loginCheckJs:
// Validate Jellyfin authentication and API responses
const res = result || {};
if (res.AccessToken) {
  src.vars.put('token', res.AccessToken);
  src.cache.put('token', res.AccessToken);
  if (res.User && res.User.Id) {
    src.vars.put('userId', res.User.Id);
    src.cache.put('userId', res.User.Id);
  }
  if (res.ServerId) {
    src.vars.put('serverId', res.ServerId);
  }
  return true;
}
if (typeof login !== 'undefined' && login && (login.user || login.password)) {
  return false;
}
if (typeof res === 'string' && (res.includes('<!DOCTYPE') || res.includes('<html'))) {
  return false;
}
if (res.error || res.ErrorMessage || res.Message === 'Unauthorized') {
  return false;
}
return true;

